import { useEffect, useState } from 'react';
import { Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';

import { addWeight, deleteWeight, getWeight } from '@/api/api';
import { NumberBoard } from '@/components/number-board';
import { PanelView } from '@/components/panel-view';
import Popup from '@/components/popup';
import { useAuth } from '@/context/AuthContext';

type WeightData = {
    userId: string;
    value: number;
    timestamp: number;
}

export default function WeightPage() {
    const { user } = useAuth();
    const [weightData, setWeightData] = useState<WeightData[]>([]);
    const fetchWeightData = async () => {
        try {
            const result = await getWeight({ userId: user.userId });
            setWeightData(result);
            let defaultValue = (result.length > 0 ? result[result.length - 1].value : 60);
            setValueInPage(defaultValue);
            setNumberBoardDefaultValue(defaultValue);
        } catch (error) {
            console.error('weight 資料抓取失敗:', error);
        }
    };
    useEffect(() => {
        fetchWeightData();
    }, []);
    const userWeight = user.weight;
    const [valueInPage, setValueInPage] = useState<number>(0);
    
    const currentTimestamp = new Date();
    const currentYear = currentTimestamp.getFullYear();
    const currentMonth = currentTimestamp.getMonth() + 1;
    const currentDay = currentTimestamp.getDate();
    const currentMonthData: WeightData[] = [];
    const [dataForChart, setDataForChart] = useState<any>([]);
    const reverseWeightData = [...weightData].reverse();
    reverseWeightData.forEach((item) => {
        const date = new Date(item.timestamp * 1000);
        date.setHours(0, 0, 0, 0);
        const month = date.getMonth() + 1;

        if (month == currentMonth) {
            currentMonthData.unshift(item);
        }
    });
    const [isAdd, setIsAdd] = useState<boolean>(false);
    const [timeOfEdit, setTimeOfEdit] = useState<number>(0);
    const [openWeightEditPopup, setOpenWeightEditPopup] = useState<boolean>(false);
    const [numberBoardDefaultValue, setNumberBoardDefaultValue] = useState<number>(0);

    async function addAndGetWeightData(selectValue: number) {
        try {
            const today = new Date();
            today.setHours(0, 0, 0, 0); // 將時、分、秒、毫秒全部設為 0，以獲取當天的開始時間
            const ms = today.getTime();
            await addWeight({ userId: user.userId, value: selectValue, timestamp: Math.floor(ms / 1000) });

            const result = await getWeight({ userId: user.userId });
            setWeightData(result);
            setValueInPage(selectValue);
            setNumberBoardDefaultValue(selectValue);
        } catch (err) {
            alert("請再試一次" + err);
        }
    }

    async function updateAndGetWeightData(selectValue: number) {
        try {
            // NoSQL的特性如果新增資料中的兩個key在資料表裡有一樣的兩個key，就會變成更新那筆資料
            await addWeight({ userId: user.userId, value: selectValue, timestamp: timeOfEdit });

            const result = await getWeight({ userId: user.userId });
            setWeightData(result);
            setValueInPage(selectValue);
            setNumberBoardDefaultValue(selectValue);
        } catch (err) {
            alert("請再試一次" + err);
        }
    }

    async function deleteAndGetWeightData(timestamp: number) {
        try {
            await deleteWeight({ userId: user.userId, timestamp: timestamp });

            const result = await getWeight({ userId: user.userId });
            setWeightData(result);
        } catch (err) {
            alert("請再試一次" + err);
        }
    }

	return (
        <PanelView>
            <ScrollView style={styles.container}>
                {weightData.length > 0 && (
                    <Pressable
                        style={styles.insertArea}
                        onPress={() => {
                            setIsAdd(true);
                            setOpenWeightEditPopup(true);
                        }}
                    >
                        <Text style={styles.addText} selectable={false}>
                            {valueInPage}
                        </Text>
                    </Pressable>
                )}
                {reverseWeightData.length > 0 && (
                    <View style={styles.otherArea}>
                        {reverseWeightData.map((v, i) => {
                            if (i > 7) {
                                return;
                            }
                            let date = new Date(v.timestamp * 1000).toLocaleDateString(
                                "zh-TW", {
                                    // year: "numeric",
                                    month: "2-digit",
                                    day: "2-digit"
                                }
                            ).split("/");
                            let month = date[0];
                            let day = date[1];

                            return (
                                <View key={`list_daily_${month}_${day}`}>
                                    <View style={styles.dayHeader}>
                                        <Text style={styles.dayHeaderText} selectable={false}>
                                            {month}月{day}日
                                        </Text>
                                    </View>
                                    <Pressable 
                                        style={({ pressed }) => [
                                            styles.itemRow, 
                                            { opacity: pressed ? 0.9 : 1 }
                                        ]}
                                        key={`daily_${month}_${day}_${v.timestamp}`}
                                        onPress={() => {
                                            setIsAdd(false);
                                            setTimeOfEdit(v.timestamp);
                                            setOpenWeightEditPopup(true);
                                        }}
                                    >
                                        <Text style={styles.itemText} selectable={false}>{v.value} kg</Text>
                                        <Pressable 
                                            style={({ pressed }) => [
                                                styles.deleteButton,
                                                { opacity: pressed ? 0.8 : 1 }
                                            ]}
                                            onPress={() => {
                                                deleteAndGetWeightData(v.timestamp);
                                            }}
                                        >
                                            <Text style={styles.deleteButtonText} selectable={false}>刪除</Text>
                                        </Pressable>
                                    </Pressable>
                                </View>
                            );
                        })}
                    </View>
                )}
            </ScrollView>

            <Popup controller={[openWeightEditPopup, setOpenWeightEditPopup]}>
                <NumberBoard
                    default={numberBoardDefaultValue}
                    setValue={isAdd ? addAndGetWeightData : updateAndGetWeightData}
                    float={false}
                    controller={[openWeightEditPopup, setOpenWeightEditPopup]}
                />
            </Popup>
        </PanelView>
    );
}

