import { DarkTheme, DefaultTheme, ThemeProvider } from '@react-navigation/native';
import { Stack, useRouter, useSegments } from 'expo-router';
import Head from 'expo-router/head';
import { StatusBar } from 'expo-status-bar';
import { useEffect } from 'react';
import { ActivityIndicator, Text, TouchableOpacity, View } from 'react-native';
import 'react-native-reanimated';

import { AuthProvider, useAuth } from '@/context/AuthContext';
import { useColorScheme } from '@/hooks/use-color-scheme';

function RootLayoutNav() {
    const colorScheme = useColorScheme();
    const segments = useSegments();
    const router = useRouter();
    // 1. 登入狀態
    const { user, isLoading } = useAuth();

    // 2. 路由守衛 (Protection Guard)
    useEffect(() => {
        if (isLoading) return;

        // 將 segments[0] 轉為 string 比對，避免 TS 強制限制 Union Type
        const currentSegment = segments[0] as string;
        const isAtLoginScreen = !currentSegment || currentSegment === 'index';

        if (!user && !isAtLoginScreen) {
            // 未登入 且 不在登入頁 -> 踢回根目錄 (index.tsx)
            router.replace('/');
        } else if (user && isAtLoginScreen) {
            // 已登入 卻還在登入頁 -> 自動導向主頁 (tabs)
            router.replace('/home');
        }
    }, [user, isLoading, segments]);

    // 3. 檢查 Token 期間顯示 Loading，避免未登入畫面閃爍
    if (isLoading) {
        return (
            <View style={{ flex: 1, justifyContent: 'center', alignItems: 'center', display: 'none' }}>
                <ActivityIndicator size="large" />
            </View>
        );
    }

    return (
        <ThemeProvider value={colorScheme === 'dark' ? DarkTheme : DefaultTheme}>
            <Stack
                screenOptions={{
                    headerLeft: () => (
                        <TouchableOpacity
                            onPress={() => {
                                if (router.canGoBack()) {
                                    router.back(); // 有上一頁，正常返回
                                } else {
                                    router.replace('/'); // 沒有上一頁（例如網頁重新整理），安全切換回首頁
                                }
                            }}
                            style={{ alignItems: 'center', width: 70, }}
                        >
                            <Text style={{ color: '#ffffff', fontSize: 20, fontWeight: '500', }}>
                                返回
                            </Text>
                        </TouchableOpacity>
                    ),
                    headerTitle: '',
                }}
            >
                {/* index 即為你的登入頁面 */}
                <Stack.Screen
                    name="index"
                    options={{ headerShown: false }}
                />
                <Stack.Screen
                    name="(tabs)"
                    options={{ headerShown: false }}
                />
                <Stack.Screen
                    name="weight"
                    options={{
                        presentation: 'modal',
                    }}
                />
                <Stack.Screen
                    name="water"
                    options={{
                        presentation: 'modal',
                    }}
                />
                <Stack.Screen
                    name="protein"
                    options={{
                        presentation: 'modal',
                    }}
                />
            </Stack>
            <StatusBar style="auto"/>
        </ThemeProvider>
    );
}

export default function RootLayout() {
    return (
        <AuthProvider>
            <Head>
                <link rel="apple-touch-icon" href="/assets/images/favicon.png" />
            </Head>
            <RootLayoutNav/>
        </AuthProvider>
    );
}
