import { Dispatch, SetStateAction, useState } from 'react';
import { Pressable, StyleSheet, Text, TextInput, View } from 'react-native';

type NumberBoardProps = {
    controller: [
        boolean,
        Dispatch<SetStateAction<boolean>>
    ];
    setValue: (value: number) => Promise<void>;
    default: number | string;
    float?: boolean;
}

export function NumberBoard(props: NumberBoardProps) {
    let submitValue = props.setValue;
    let defaultValue = props.default || 50;
    let enableDot = props.float === undefined ? true : props.float;
    let [open, setOpen] = props.controller;
    const [currentValue, setCurrentValue] = useState(String(defaultValue));
    let numberKeyboard = [7, 8, 9, 4, 5, 6, 1, 2, 3, 0, '.', '←'];

    // 如果沒開啓，直接回傳 null 不渲染
    if (!open) return null;

    return (
        <View style={styles.container}>
            
            <TextInput
                editable={false}
                value={String(currentValue)}
                placeholder={enableDot ? '0.0' : '0'}
                style={styles.input}
            />

            <View style={styles.gridContainer}>
                {numberKeyboard.map((num, index) => {
                    const isDisabled = num === '.' && !enableDot;
                    return (
                        <Pressable
                            key={index}
                            disabled={isDisabled}
                            style={({ pressed }) => [
                                styles.keyButton,
                                isDisabled && styles.disabledButton,
                                { opacity: pressed ? 0.7 : 1 }
                            ]}
                            onPress={() => {
                                let stringCurrentValue = String(currentValue);
                                let result = '';
                                
                                if (num === '←') {
                                    result = stringCurrentValue.slice(0, -1);
                                } else if (num === '.') {
                                    if (!stringCurrentValue.includes('.')) {
                                        result = stringCurrentValue + num;
                                    } else {
                                        result = stringCurrentValue;
                                    }
                                } else {
                                    if (stringCurrentValue === '0' && num !== '.') {
                                        result = String(num);
                                    } else {
                                        result = stringCurrentValue + num;
                                    }
                                }
                                setCurrentValue(result);
                            }}
                        >
                            <Text style={styles.keyText}>{num}</Text>
                        </Pressable>
                    );
                })}
            </View>

            <View style={styles.buttonContainer}>
                <Pressable
                    style={({ pressed }) => [styles.actionButton, styles.confirmButton, { opacity: pressed ? 0.8 : 1 }]}
                    onPress={() => {
                        submitValue(Number(currentValue));
                        setOpen(false);
                    }}
                >
                    <Text style={styles.actionButtonText}>確定</Text>
                </Pressable>
                
                <Pressable
                    style={({ pressed }) => [styles.actionButton, styles.cancelButton, { opacity: pressed ? 0.8 : 1 }]}
                    onPress={() => {
                        setOpen(false);
                    }}
                >
                    <Text style={styles.actionButtonText}>取消</Text>
                </Pressable>
            </View>
        </View>
    );
}

const styles = StyleSheet.create({
    container: {
        width: '100%',
        backgroundColor: '#ffffff',
        alignItems: 'center',
        padding: 16,
    },
    input: {
        width: '100%',
        maxWidth: 400,
        height: 100,
        textAlign: 'center',
        fontSize: 64,
        color: '#000000',
        marginBottom: 20,
    },
    gridContainer: {
        width: '100%',
        maxWidth: 400,
        flexDirection: 'row',
        flexWrap: 'wrap',
        justifyContent: 'space-between',
        marginBottom: 16,
    },
    keyButton: {
        width: '31%',
        aspectRatio: 1.5,
        backgroundColor: '#e5e7eb',
        justifyContent: 'center',
        alignItems: 'center',
        borderRadius: 8,
        marginBottom: 10,
    },
    disabledButton: {
        opacity: 0.4,
    },
    keyText: {
        fontSize: 24,
        fontWeight: '500',
        color: '#000000',
    },
    buttonContainer: {
        flexDirection: 'row',
        justifyContent: 'center',
        gap: 12,
        marginBottom: 16,
    },
    actionButton: {
        paddingHorizontal: 24,
        paddingVertical: 10,
        borderRadius: 8,
        marginHorizontal: 6,
    },
    confirmButton: {
        backgroundColor: '#3b82f6',
    },
    cancelButton: {
        backgroundColor: '#ef4444',
    },
    actionButtonText: {
        color: '#ffffff',
        fontSize: 16,
        fontWeight: '500',
    },
});