import { isMobileBrowser } from '@/constants/tool';
import { Image } from 'expo-image';
import { Tabs, router } from 'expo-router';
import React from 'react';
import { Platform, StyleSheet } from 'react-native';

import { HapticTab } from '@/components/haptic-tab';
import { Colors } from '@/constants/theme';
import { useColorScheme } from '@/hooks/use-color-scheme';

export default function TabLayout() {
    const colorScheme = useColorScheme();

    return (
        <Tabs
            screenOptions={{
                tabBarActiveTintColor: Colors[colorScheme ?? 'light'].tint,
                tabBarInactiveTintColor: Colors[colorScheme ?? 'light'].tint,
                headerShown: false,
                tabBarButton: HapticTab,
                tabBarStyle: styles.tabBarStyle,
                tabBarShowLabel: Platform.OS === 'web' && !isMobileBrowser(),
                tabBarLabelStyle: styles.tabLabelStyle,
            }}
        >
            <Tabs.Screen
                name="home"
                options={{ 
                    href: null, // 設定為 null 就不會在底部選單渲染出來
                }}
            />
            <Tabs.Screen
                name="weight-blank"
                options={{
                    title: 'weight',
                    tabBarIcon: () => (
                        <Image
                            source={require('@/assets/images/weight-removebg.png')}
                            style={styles.tabImage}
                        />
                    ),
                }}
                listeners={{
                    tabPress: (e) => {
                        e.preventDefault(); // 阻止 Tab 預設切換行為
                        router.push('/weight'); // 開啟 Stack 裡的 modal 頁面
                    },
                }}
            />
            <Tabs.Screen
                name="water-blank"
                options={{
                    title: 'water',
                    tabBarIcon: () => (
                        <Image
                            source={require('@/assets/images/water-removebg.png')}
                            style={styles.tabImage}
                        />
                    ),
                }}
                listeners={{
                    tabPress: (e) => {
                        e.preventDefault();
                        router.push('/water');
                    },
                }}
            />
            <Tabs.Screen
                name="protein-blank"
                options={{
                    title: 'protein',
                    tabBarIcon: () => (
                        <Image
                            source={require('@/assets/images/protein-removebg.png')}
                            style={styles.tabImage}
                        />
                    ),
                }}
                listeners={{
                    tabPress: (e) => {
                        e.preventDefault();
                        router.push('/protein');
                    },
                }}
            />
        </Tabs>
    );
}

const styles = StyleSheet.create({
    tabBarStyle: {
        position: 'absolute',
        backgroundColor: 'rgba(255, 255, 255, 0.8)',
        borderTopWidth: 0,          // 移除頂部分隔線
        paddingBottom: 10,          // 內距（避開手機底部 indicator）
        ...Platform.select({
            default: {
                height: 100,
                paddingTop: 30,
            },
            web: {
                height: isMobileBrowser() ? 100 : 50,
                paddingTop: isMobileBrowser() ? 30 : 10,
            },
        }),
    },
    tabImage: {
        ...Platform.select({
            default: {
                width: 100,
                height: 100,
            },
            web: {
                width: isMobileBrowser() ? 100 : 50,
                height: isMobileBrowser() ? 100 : 50,
            },
        }),
    },
    tabLabelStyle: {
        color: '#000000',
        marginLeft: 50,
    }
});
